const prepare = function prepareSpeech({ input_text, voice }) {
  if (typeof input_text !== 'string' || !input_text.trim()) throw new Error('Input text is required.');
  if (Array.from(input_text).length > 4096) throw new Error('Input text must contain at most 4096 characters.');
  const selected = voice == null || voice === '' ? 'alloy' : voice;
  if (!['alloy', 'ash', 'coral', 'echo', 'fable', 'onyx', 'nova', 'sage', 'shimmer'].includes(selected)) throw new Error('Choose a supported tts-1 voice.');
  return { input_text, voice: selected };
}

return $input.all().map((item,index)=>({json:prepare(item.json),pairedItem:{item:index}}));

const items = $input.all();
const result = [];
for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const audio = item.binary?.data;
  const type = typeof audio?.mimeType === 'string' ? audio.mimeType.split(';')[0].trim().toLowerCase() : '';
  if (!['audio/mpeg', 'audio/mp3', 'application/octet-stream'].includes(type)) throw new Error('The speech response is not MP3 audio.');
  const bytes = await this.helpers.getBinaryDataBuffer(index, 'data');
  if (!bytes.length) throw new Error('The speech response is empty.');
  result.push({...item, binary:{...item.binary,data:{...audio,fileName:'speech.mp3',mimeType:'audio/mpeg'}},pairedItem:{item:index}});
}
return result;
